output:
```python
names = ['Ada', 'Alan', 'Grace']
for index, name in enumerate(names):
    print(index, name)

for line_no, line in enumerate(open('app.log'), start=1):
    if 'ERROR' in line:
        print(f'line {line_no}: {line.strip()}')
```

`enumerate(seq, start=1)` saves you maintaining a counter by hand. For two lists in step, use `for a, b in zip(list_a, list_b)`; add `strict=True` in Python 3.10+ to catch length mismatches.

```python
for n in range(10):
    if n == 3:
        continue   # skip this turn
    if n == 7:
        break      # leave the loop entirely
    print(n)
```

`continue` skips the rest of the body and goes to the next item; `break` exits the loop. `for` loops can take an `else` block that runs only if no break happened — useful for searches. Do not use break to escape nested loops: move the inner work into a function and return instead.

```python
import json

try:
    with open('config.json', encoding='utf-8') as f:
        config = json.load(f)
except FileNotFoundError:
    config = {}
except json.JSONDecodeError as err:
    print(f'bad json: {err}')
else:
    print('loaded', len(config), 'keys')
finally:
    print('done')
```

Catch the specific exception you expect, not bare `except:`. `else` runs when no error happened, `finally` always runs. Do not wrap a whole program in try/except — handle errors where you can actually do something about them.

```python
def percentage(part, whole):
    if whole == 0:
        raise ValueError('whole cannot be zero')
    if not 0 <= part <= whole:
        raise ValueError(f'part {part} outside 0..{whole}')
    return part / whole * 100
```

Fail early with a message that says what was wrong and what was expected. Re-raise with `raise` (no argument) when you only wanted to log:

```python
try:
    do_work()
except RuntimeError:
    print('failed, re-raising')
    raise
```

A readable interpreter loop with validation and a safe operator table.

```python
import operator

OPS = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}

def calculate(left, op, right):
    if op not in OPS:
        raise ValueError(f'unknown operator {op!r}')
    if op == '/' and right == 0:
        raise ZeroDivisionError('cannot divide by zero')
    return OPS[op](left, right)

def main():
    while True:
        raw = input('calc> ').strip()
        if raw in ('q', 'quit'):
            break
        parts = raw.split()
        if len(parts) != 3:
            print('use: number operator number')
            continue
        try:
            left, op, right = float(parts[0]), parts[1], float(parts[2])
            print(calculate(left, op, right))
        except (ValueError, ZeroDivisionError) as err:
            print('error:', err)

if __name__ == '__main__':
    main()
```

Parsing and calculating are separate so each can be tested. Never `eval()` user input.

Download JSON with a timeout, handle HTTP errors and write it to disk only when it parsed correctly.

```python
import json
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.request import urlopen

URL = 'https://api.github.com/repos/python/cpython'

def fetch(url, timeout=10):
    with urlopen(url, timeout=timeout) as response:
        return json.load(response)

try:
    data = fetch(URL)
except HTTPError as err:
    print('http error', err.code, err.reason)
except URLError as err:
    print('network error', err.reason)
except json.JSONDecodeError as err:
    print('not json:', err)
else:
    Path('repo.json').write_text(json.dumps(data, indent=2), encoding='utf-8')
    print('saved stars:', data.get('stargazers_count'))
```

Separate fetching from saving so a failed parse cannot leave a half-written file. `timeout` stops a dead server from hanging the script.

Print the most common words in notes.txt:

```python
#!/usr/bin/env python3
"""Print the most common words in notes.txt."""

import re
import sys
from collections import Counter

STOPWORDS = {
    "the", "a", "an", "and", "or", "of", "to", "in", "is", "it", "that",
    "for", "on", "with", "as", "at", "be", "this", "by", "from", "was",
}


def top_words(path, limit=10):
    text = open(path, encoding="utf-8").read().lower()
    words = re.findall(r"[a-z']+", text)
    return Counter(w for w in words if w not in STOPWORDS).most_common(limit)


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else "notes.txt"
    for word, count in top_words(path):
        print(f"{word:<20} {count}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

