#!/usr/bin/env python3
"""Sort sales.csv by amount, biggest first."""

import csv
import sys


def sortable(value):
    try:
        return (0, float(value.replace(",", "")))
    except (AttributeError, ValueError):
        return (1, str(value).lower())


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else "sales.csv"
    with open(path, newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    if not rows:
        print("no rows found")
        return 1
    rows.sort(key=lambda row: sortable(row.get("amount", "")), reverse=True)
    target = path.rsplit(".", 1)[0] + "-sorted.csv"
    with open(target, "w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=rows[0].keys())
        writer.writeheader()
        writer.writerows(rows)
    for row in rows[:5]:
        print(row.get("amount"), "-", row)
    print(f"{len(rows)} rows written to {target}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
