"""Load config.json, filling in defaults when keys are missing."""

import json
from pathlib import Path

SETTINGS = Path("config.json")
DEFAULTS = {"theme": "dark", "volume": 5, "recent": []}


def load():
    if not SETTINGS.exists():
        return dict(DEFAULTS)
    with SETTINGS.open(encoding="utf-8") as handle:
        data = json.load(handle)
    return {**DEFAULTS, **data}


def save(settings):
    SETTINGS.write_text(json.dumps(settings, indent=2), encoding="utf-8")


def main():
    settings = load()
    print("loaded:", settings)
    settings["recent"].append("onyx")
    save(settings)
    print("saved to", SETTINGS)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

