Watch downloads and print new files as they arrive:

```python
#!/usr/bin/env python3
"""Watch downloads and report files that appear or disappear."""

import time
from pathlib import Path

FOLDER = Path("downloads")
INTERVAL = 5


def snapshot(folder):
    return {path.name for path in folder.iterdir() if path.is_file()}


def main():
    known = snapshot(FOLDER)
    print(f"watching {FOLDER} every {INTERVAL}s")
    while True:
        time.sleep(INTERVAL)
        current = snapshot(FOLDER)
        for name in sorted(current - known):
            print(f"new:  {name}")
        for name in sorted(known - current):
            print(f"gone: {name}")
        known = current


if __name__ == "__main__":
    raise SystemExit(main())
```

